function InteractiveReader({data}) { const nodes=Array.isArray(data?.nodes)?data.nodes:[]; const [nodeId,setNodeId]=useState(data?.start||nodes[0]?.id); const scene=nodes.find(n=>n.id===nodeId)||nodes[0]; const sceneRef=useRef(null); useEffect(()=>{sceneRef.current?.scrollIntoView({behavior:'smooth',block:'start'});},[nodeId]); if(!scene)return <p>Сценарий интерактивной книги пока не настроен.</p>; const illustration=(url,alt)=>url?<figure className="reader-figure chapter-illustration"><img src={url} alt={alt||'Иллюстрация главы'}/></figure>:null; return <div className="interactive-reader" ref={sceneRef}><div className="interactive-scene"><div className="interactive-scene-label">ВАШ ВЫБОР · {scene.title||scene.id}</div>{illustration(scene.image_start,scene.image_start_alt)}{(scene.text||'').split(/\n\s*\n/).map((p,i)=><p key={i}>{p}</p>)}{illustration(scene.image_end,scene.image_end_alt)}</div>{scene.choices?.length?<div className="interactive-choices"><div className="interactive-prompt">Что будете делать?</div>{scene.choices.map((choice,i)=><button key={i} style={{backgroundColor:choice.buttonColor||'#563b78',color:choice.textColor||'#fff'}} onClick={()=>{if(nodes.some(n=>n.id===choice.target))setNodeId(choice.target);}}>{choice.label}</button>)}</div>:<div className="interactive-ending"><b>Конец этой истории</b><button onClick={()=>setNodeId(data.start||nodes[0].id)}>Начать заново</button></div>}</div>; }
function ReaderQuestions({questions}) { const [opened,setOpened]=useState({}); const answerRefs=useRef({}); useEffect(()=>{const index=Object.keys(opened).find(k=>opened[k]&&answerRefs.current[k]);if(index!==undefined)answerRefs.current[index]?.scrollIntoView({behavior:'smooth',block:'center'});},[opened]); return questions?.length?<section className="reader-questions"><div className="interactive-scene-label">ПРОВЕРЬ СЕБЯ</div><h2>Вопросы к читателю</h2>{questions.map((q,i)=><div className="reader-question" key={i}><h3>{i+1}. {q.question}</h3><button onClick={()=>setOpened(v=>({...v,[i]:!v[i]}))}>{opened[i]?'Скрыть ответ':'Показать ответ'}</button>{opened[i]&&<div className="reader-answer" ref={el=>answerRefs.current[i]=el}>{q.answer}</div>}</div>)}</section>:null; }
