async function upload(file){if(!file)return null;if(!configured)throw Error('Сначала подключи Supabase.');const ext=file.name.split('.').pop()||'jpg',path=Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext;const {error}=await supabase.storage.from('gallery').upload(path,file,{upsert:true,contentType:file.type||undefined});if(error)throw error;return supabase.storage.from('gallery').getPublicUrl(path).data.publicUrl}
async function insertIllustrations(files){
const list=Array.from(files||[]);if(!list.length)return;
setUploadingIllustration(true);setError('');
try{
const urls=[];
for(const file of list){
if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('Поддерживаются PNG, JPG, JPEG, WebP и GIF.');
if(file.size>15*1024*1024)throw Error('Размер одной иллюстрации не должен превышать 15 МБ.');
const url=await upload(file);urls.push({url,name:file.name.replace(/\.[^.]+$/,'').replace(/[\[\]()]|!/g,' ')});
}
const area=contentRef.current;const source=form.book_content||'';const start=area?.selectionStart??source.length;const end=area?.selectionEnd??source.length;
const block=urls.map(x=>'!['+x.name+']('+x.url+')').join('\n\n');
const before=source.slice(0,start),after=source.slice(end);
const prefix=before&& !before.endsWith('\n\n')?'\n\n':'';
const suffix=after&& !after.startsWith('\n\n')?'\n\n':'';
const next=before+prefix+block+suffix+after;
setForm(v=>({...v,book_content:next}));
requestAnimationFrame(()=>{if(area){const pos=(before+prefix+block).length;area.focus();area.setSelectionRange(pos,pos);}});
setNotice('Иллюстрация добавлена в текст');
}catch(e){setError(e.message||'Не удалось загрузить иллюстрацию.');}
finally{setUploadingIllustration(false);if(illustrationInputRef.current)illustrationInputRef.current.value='';}
}
